"""Frozen late-season away favorite rule. Never use cached research ranks as live inputs."""
from pathlib import Path
from datetime import datetime,timezone,timedelta
from concurrent.futures import ThreadPoolExecutor
from zoneinfo import ZoneInfo
import io,json,hashlib
import numpy as np,pandas as pd,requests
RULE='late_road_protection_rest_v1'
ALIASES={'SD':'LAC','OAK':'LV','STL':'LA','LAR':'LA'}
OL=['C','G','T','OT','OG','LT','LG','RT','RG']
def qualifies(week,prior_games,opp_prior_games,defense_edge,continuity,opponent_protection_rank,rest_edge,moneyline):
 vals=[week,prior_games,opp_prior_games,defense_edge,continuity,opponent_protection_rank,rest_edge,moneyline]
 if any(v is None or not np.isfinite(v) for v in vals):return False
 return 11<=week<=18 and min(prior_games,opp_prior_games)>=4 and defense_edge>=8 and continuity>=.6 and -400<=moneyline< -200 and not(opponent_protection_rank<=8 and rest_edge<0)
def refresh(root,season):
 cache=root/'late_season_inputs';cache.mkdir(exist_ok=True)
 def one(kind,stem):
  url=f'https://github.com/nflverse/nflverse-data/releases/download/{kind}/{stem}_{season}.parquet'
  response=requests.get(url,timeout=(5,25));response.raise_for_status();data=response.content
  frame=pd.read_parquet(io.BytesIO(data));path=cache/f'{stem}_{season}.parquet';tmp=path.with_suffix('.tmp');tmp.write_bytes(data);tmp.replace(path)
  (cache/f'{stem}_{season}.json').write_text(json.dumps({'source':url,'retrieved_at':datetime.now(timezone.utc).isoformat(),'sha256':hashlib.sha256(data).hexdigest()},indent=2))
  return frame
 with ThreadPoolExecutor(max_workers=2) as p:
  ft=p.submit(one,'stats_team','stats_team_week');fs=p.submit(one,'snap_counts','snap_counts');return ft.result(),fs.result()
def build_profiles(G,T,S,season,week):
 # Require all earlier-week scores and statistics; don't predict a future week with partial prior-week data.
 prior=G[G.season.eq(season)&G.game_type.eq('REG')&G.week.lt(week)].copy()
 if prior.empty or prior[['home_score','away_score']].isna().any().any():raise ValueError('Prior weeks not complete')
 sides=pd.concat([prior[['game_id','season','week','home_team','away_team']].rename(columns={'home_team':'team','away_team':'opponent'}),prior[['game_id','season','week','away_team','home_team']].rename(columns={'away_team':'team','home_team':'opponent'})])
 t=T[T.season.eq(season)&T.season_type.eq('REG')&T.week.lt(week)].copy();t.team=t.team.replace(ALIASES)
 cols=['season','week','team','passing_epa','attempts','sacks_suffered']
 j=sides.merge(t[cols],on=['season','week','team'],how='left',validate='one_to_one');db=j.attempts+j.sacks_suffered
 if j[cols].isna().any().any() or (db<=0).any():raise ValueError('Incomplete prior team statistics')
 j['pass_epa']=j.passing_epa/db;j['sack_rate']=j.sacks_suffered/db
 defense=j.groupby('opponent').pass_epa.mean().rank(method='average');protection=j.groupby('team').sack_rate.mean().rank(method='average');counts=j.groupby('team').size()
 if len(defense)!=32 or len(protection)!=32:raise ValueError('Incomplete league ranking universe')
 snaps=S.copy();snaps.team=snaps.team.replace(ALIASES);continuity={}
 for team,h in j.groupby('team'):
  ids=h.sort_values(['week','game_id']).tail(2).game_id.tolist();lineups=[]
  for gid in ids:
   a=snaps[snaps.game_id.eq(gid)&snaps.team.eq(team)&snaps.position.isin(OL)].sort_values(['offense_snaps','pfr_player_id'],ascending=[False,True]).head(5)
   players=set(a.pfr_player_id.dropna());lineups.append(players)
  continuity[team]=len(lineups[0]&lineups[1])/5 if len(lineups)==2 and all(len(v)==5 for v in lineups) else np.nan
 return {t:dict(defense_rank=float(defense[t]),protection_rank=float(protection[t]),prior_games=int(counts[t]),continuity=float(continuity[t])) for t in defense.index}
def scan(G,root,now,odds_fetch):
 upcoming=[]
 for x in G[G.game_type.eq('REG')&G.week.ge(11)&G.week.le(18)].itertuples():
  if pd.notna(x.home_score) or pd.notna(x.away_score) or pd.isna(x.gametime):continue
  kickoff=datetime.fromisoformat(x.gameday+'T'+x.gametime).replace(tzinfo=ZoneInfo('America/New_York')).astimezone(timezone.utc)
  if now<kickoff<=now+timedelta(days=7):upcoming.append((x,kickoff))
 status={'rule':RULE,'checked_at':now.isoformat(),'upcoming_week11plus_games':len(upcoming),'matches':0,'issues':[]}
 if not upcoming:status['status']='No Week 11+ games within seven days';return [],status
 frames={};profiles={};failures={};candidates=[]
 for x,kickoff in upcoming:
  try:
   if x.season in failures:raise ValueError(failures[x.season])
   if x.season not in frames:
    try:frames[x.season]=refresh(root,x.season)
    except Exception as e:failures[x.season]='Fresh season feed unavailable: '+type(e).__name__;raise
   key=(x.season,x.week)
   if key not in profiles:profiles[key]=build_profiles(G,*frames[x.season],*key)
   a=profiles[key][x.away_team];h=profiles[key][x.home_team];edge=h['defense_rank']-a['defense_rank'];rest=x.away_rest-x.home_rest
   if not qualifies(x.week,a['prior_games'],h['prior_games'],edge,a['continuity'],h['protection_rank'],rest,-300):continue
   rec=dict(game_id=x.game_id,season=int(x.season),week=int(x.week),home=x.home_team,away=x.away_team,selection_side='away',selected_team=x.away_team,rules=[RULE],kickoff=kickoff.isoformat(),espn=str(int(x.espn)),observed_at=now.isoformat(),rule_version=RULE,late_profile={'defense_rank':a['defense_rank'],'opponent_defense_rank':h['defense_rank'],'defense_edge':edge,'ol_continuity':a['continuity'],'opponent_protection_rank':h['protection_rank'],'rest_edge':float(rest),'prior_games':a['prior_games'],'opponent_prior_games':h['prior_games']})
   candidates.append(rec)
  except Exception as e:status['issues'].append({'game_id':x.game_id,'error':type(e).__name__+': '+str(e)[:160]})
 with ThreadPoolExecutor(max_workers=4) as pool:
  for r,odds in zip(candidates,pool.map(odds_fetch,candidates)):r['odds']=odds
 records=[]
 for r in candidates:
  p=r['late_profile'];o=r['odds'];price=o.get('moneyline')
  if price is None:status['issues'].append({'game_id':r['game_id'],'error':'Current away moneyline unavailable; no signal emitted'});continue
  stamp=o.get('retrieved_at');fresh=stamp and abs((now-datetime.fromisoformat(stamp)).total_seconds())<=900
  if not fresh:status['issues'].append({'game_id':r['game_id'],'error':'Stale or missing odds observation time'});continue
  if qualifies(r['week'],p['prior_games'],p['opponent_prior_games'],p['defense_edge'],p['ol_continuity'],p['opponent_protection_rank'],p['rest_edge'],price):records.append(r)
 status['matches']=len(records);status['status']='Needs data/odds attention' if status['issues'] else 'Complete';return records,status
